from pathlib import Path
import ast
ROOT=Path(__file__).resolve().parent
PKG=ROOT/"qseries_v2/oracle_execution/solana_atomic_executor"
MODULE='"""MTR-158: unsigned compiled-v0 transaction artifact handoff. Offline only."""\nimport argparse\nimport base64\nimport hashlib\nimport json\nfrom pathlib import Path\nfrom .mtr_153_v0_alt_account_resolver import _parse_v0\nfrom .mtr_157_canonical_compiled_v0_handoff import CANONICAL\n\nclass HandoffHold(ValueError):\n    pass\n\ndef validate(raw):\n    if type(raw) is not bytes or not 1 <= len(raw) <= 1232:\n        raise HandoffHold("INVALID_TRANSACTION_SIZE")\n    # Only an unsigned placeholder-signature envelope may be exported.\n    try:\n        from .mtr_152_native_envelope_inspector import _short\n        n, offset = _short(raw, 0)\n        if not 1 <= n <= 64 or offset + n * 64 >= len(raw):\n            raise HandoffHold("INVALID_SIGNATURE_SECTION")\n        if any(raw[offset:offset + n * 64]):\n            raise HandoffHold("SIGNED_TRANSACTION_REJECTED")\n        static, ins, lookups = _parse_v0(raw)\n    except HandoffHold:\n        raise\n    except Exception as exc:\n        raise HandoffHold("INVALID_V0_ENVELOPE") from exc\n    if not lookups or CANONICAL not in [t for t, _, _ in lookups]:\n        raise HandoffHold("CANONICAL_ALT_NOT_REFERENCED")\n    return {\n        "sha256": hashlib.sha256(raw).hexdigest(),\n        "bytes": len(raw),\n        "instruction_count": len(ins),\n        "table_ids": [t for t, _, _ in lookups],\n        "unsigned_placeholder": True,\n        "protected_bounds_verified": False,\n        "atomic_two_leg_proven": False,\n        "broadcast_authorized": False,\n    }\n\ndef stage(source, output_dir):\n    source = Path(source)\n    # Explicit source only; never search folders or invoke compiler/signer.\n    if not source.is_file() or source.stat().st_size > 4096:\n        raise HandoffHold("SOURCE_MISSING_OR_TOO_LARGE")\n    try:\n        raw = base64.b64decode(source.read_text(encoding="ascii").strip(), validate=True)\n    except Exception as exc:\n        raise HandoffHold("INVALID_BASE64") from exc\n    report = validate(raw)\n    directory = Path(output_dir)\n    directory.mkdir(parents=True, exist_ok=True)\n    tx = directory / "mtr_158_unsigned_compiled_v0.b64"\n    evidence = directory / "mtr_158_unsigned_compiled_v0.json"\n    tx.write_text(base64.b64encode(raw).decode("ascii") + "\\n", encoding="ascii")\n    evidence.write_text(json.dumps(report, indent=2) + "\\n", encoding="utf-8")\n    return report, tx, evidence\n\ndef main(argv=None):\n    parser = argparse.ArgumentParser()\n    parser.add_argument("--input-base64-file", type=Path)\n    parser.add_argument("--output-dir", type=Path, default=Path.cwd() / "runtime_state/oracle/oracle_live_execution")\n    args = parser.parse_args(argv)\n    if args.input_base64_file:\n        try:\n            report, tx, evidence = stage(args.input_base64_file, args.output_dir)\n        except HandoffHold as exc:\n            raise SystemExit("[HOLD] " + str(exc)) from exc\n        print("[MTR158_TX_SHA256]", report["sha256"])\n        print("[MTR158_ARTIFACT]", tx)\n        print("[MTR158_EVIDENCE]", evidence)\n        print("[MTR158_ALT_REF]", ",".join(report["table_ids"]))\n        print("[MTR158_LINK] OFFLINE_ARTIFACT_READY")\n    else:\n        print("[MTR158] UNSIGNED_COMPILED_ARTIFACT_HANDOFF_READY")\n        print("[MTR158_LINK] HOLD_NO_COMPILED_INPUT")\n    print("[COMPILER_INVOKED] FALSE")\n    print("[RPC] NOT_CALLED")\n    print("[PROTECTED_PROFIT] FALSE")\n    print("[PRIVATE_KEY] NOT_USED")\n    print("[SIGNING] FALSE")\n    print("[BROADCAST] FALSE")\n\nif __name__ == "__main__":\n    main()\n'
TEST='import base64\nimport tempfile\nimport unittest\nfrom pathlib import Path\nfrom qseries_v2.oracle_execution.solana_atomic_executor import mtr_158_unsigned_compiled_handoff as m\nfrom qseries_v2.oracle_execution.solana_atomic_executor.mtr_152_native_envelope_inspector import _base58\n\ndef sample(table, sig=bytes(64)):\n    return (bytes((1,)) + sig + bytes((128,1,0,2,3)) +\n        bytes([11])*32 + bytes([12])*32 + bytes([13])*32 +\n        bytes([14])*32 + bytes((1,1,0,1,9,1)) +\n        table + bytes((1,0,0)))\n\ndef decode58(s):\n    alphabet="123456789ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz"\n    n=0\n    for c in s:\n        n=n*58+alphabet.index(c)\n    return n.to_bytes(32,"big")\n\nclass T(unittest.TestCase):\n    def test_unsigned_canonical(self):\n        \n        raw=sample(decode58(m.CANONICAL))\n        out=m.validate(raw)\n        self.assertTrue(out["unsigned_placeholder"])\n        self.assertFalse(out["protected_bounds_verified"])\n        self.assertFalse(out["broadcast_authorized"])\n    def test_signed_rejected(self):\n        \n        with self.assertRaises(m.HandoffHold):\n            m.validate(sample(decode58(m.CANONICAL), b"\\x01"+bytes(63)))\n    def test_other_alt_rejected(self):\n        with self.assertRaises(m.HandoffHold):\n            m.validate(sample(bytes([8])*32))\n    def test_malformed_rejected(self):\n        with self.assertRaises(m.HandoffHold):\n            m.validate(b"bad")\n    def test_explicit_artifact_only(self):\n        \n        with tempfile.TemporaryDirectory() as d:\n            src=Path(d)/"input.b64"\n            src.write_text(base64.b64encode(sample(decode58(m.CANONICAL))).decode(),encoding="ascii")\n            r,tx,ev=m.stage(src,Path(d)/"output")\n            self.assertEqual(m.validate(base64.b64decode(tx.read_text())),r)\n            self.assertTrue(ev.is_file())\n    def test_no_compiler_or_signer(self):\n        import inspect\n        src=inspect.getsource(m.stage)\n        self.assertNotIn("compile_current(",src)\n        self.assertNotIn("signed_tx(",src)\n        self.assertNotIn("simulate_current(",src)\nif __name__=="__main__":\n    unittest.main(verbosity=2)\n'
for dependency in ("mtr_153_v0_alt_account_resolver.py","mtr_157_canonical_compiled_v0_handoff.py"):
    if not (PKG/dependency).is_file():
        raise SystemExit("[HOLD] missing "+dependency)
ast.parse(MODULE)
ast.parse(TEST)
(PKG/"mtr_158_unsigned_compiled_handoff.py").write_text(MODULE,encoding="utf-8")
(ROOT/"test_mtr_158_unsigned_compiled_handoff.py").write_text(TEST,encoding="utf-8")
print("[PASS] MTR-158 installed")
print("[SCOPE] EXPLICIT_UNSIGNED_COMPILED_ARTIFACT_ONLY")
print("[SCANNER] FROZEN")
print("[PRIVATE_KEY] NOT_USED")
print("[SIGNING] FALSE")
print("[BROADCAST] FALSE")
